   283:      const localDoses = doseList.map((d) => (d.id === pendingDose.id ? { ...d, status: "taken" as const, eventAt: occurredAt } : d));
   284:      setDoseList(localDoses);
   285:      const localEvent: DoseEvent = { id: `local-${pendingDose.id}-${occurredAt}`, ...doseEvent };
   286:      const input = buildAgentInputFromState({
   287:        now: occurredAt,
   288:        userId: demoUser.id,
   289:        dogId: demoDog.id,
